VALUES ('club_haymarket-old-dominion-mahjong', 'Old Dominion Mahjong', 'haymarket-old-dominion-mahjong', 'Organiser of public mahjong events on Eventbrite. Its own event listing says: "Our beginner-friendly Mahjong 101 lesson introduces the fundamentals of American mahjong through thoughtful, step-by-step instruction". Venues are public (Aroma II Tasting Room; Great Mane Brewery; Winery at La Grange). The organiser''s own website has not been checked.', (SELECT id FROM City WHERE name = 'Haymarket' AND state = 'VA'), 'Haymarket, VA', NULL, NULL, NULL, NULL, NULL, 1, 1, 1, 1, 0, 0, NULL, 'Events listed on Eventbrite', 'https://www.eventbrite.com/o/old-dominion-mahjong', '2026-10-27', 'ACTIVE')
