UPDATE "Event" SET "clubId" = 'club_haymarket-old-dominion-mahjong', "status" = 'ACTIVE', "lastVerifiedAt" = '2026-10-27', "updatedAt" = CURRENT_TIMESTAMP WHERE "cityId" = (SELECT id FROM City WHERE name = 'Haymarket' AND state = 'VA') AND "clubId" IS NULL AND "status" = 'NEEDS_REVIEW' AND ("venue" LIKE '%Aroma II%' OR "venue" LIKE '%Great Mane%' OR "venue" LIKE '%La Grange%') AND "startTime" IS NOT NULL AND "eventDate" >= '2026-10-27';
-- Cities that now have five or more active rows: published with a written intro.
UPDATE "City" SET "published" = 1, "intro" = 'Haymarket''s mahjong happens in tasting rooms and breweries. Old Dominion Mahjong teaches American mahjong at Aroma II Tasting Room and Great Mane Brewery, with Mahjong 101 and 102 classes, open play nights and seasonal afternoons at the Winery at La Grange. Blue Ridge Mahj adds beginner lessons and open play at Trouvaille Brewing Company. Both groups welcome newcomers. If you have never played, book a Mahjong 101 class and learn the basics before an open play night.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'haymarket' AND "published" = 0;
UPDATE "City" SET "published" = 1, "intro" = 'New York''s American mahjong is spread across studios, synagogues and restaurants. Sparrow''s Nest Studio and Congregation Habonim both run beginner classes and open play, So Bam Fun New York and UES Mahjong teach lessons, and Mahj NYC pairs a Greek lunch on Amsterdam Avenue with a game. Beginner nights are also held in Midtown, with tiles provided. Open play is for people who already know the game, so new players should start with a beginner class.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'new-york' AND "published" = 0;
UPDATE "City" SET "published" = 1, "intro" = 'Orlando players can join the Orlando Mah Jongg Club for weekly American games at venues around the area, using the National Mah Jongg League card. Mahj & Away hosts public events with beginner lessons and open play across Central Florida, and My Mahjong Room teaches an American mahjong class at Swirlery and runs open play there. RSVP is needed for the club games. If you are new, a beginner class is a gentle way in.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'orlando' AND "published" = 0;
UPDATE "City" SET "published" = 1, "intro" = 'In Albany, the Albany JCC offers Learn to Play Mah Jongg classes taught by Ruth Malka, with drop-in game afternoons, and Vicariously Heidi runs a fast-paced introduction to American mahjong at The Hollow Bar + Kitchen downtown. Rhona Koretzky teaches multi-session American mahjong classes at libraries in the Capital Region. Check each group''s page for the next dates. If you are new, start with the introductory class at the JCC.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'albany' AND "published" = 0;
UPDATE "City" SET "published" = 1, "intro" = 'In Johns Creek, the Johns Creek Mahjong League plays open play at The Patio Cafe & Bakery on State Bridge Road, with morning and evening sessions during the week. Players bring their National Mah Jongg League card, and you can grab a bite or take dinner home while you play. The league is the one regular game in town, so check the schedule before you go. If you are still learning the rules, practice the basics first and then join an open play session.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'johns-creek' AND "published" = 0;
